import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { socket } from './socket';
import './DMPage.css';

const DMPage = ({ currentUser }) => {
  const navigate = useNavigate();
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [dmList, setDmList] = useState([]);
  const [selectedChat, setSelectedChat] = useState(null);
  const [conversations, setConversations] = useState([]);
  const [applications, setApplications] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef(null);

  // Scroll to bottom of messages
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Fetch user details helper
  const fetchUserDetails = async (userId) => {
    try {
      const response = await axios.get(`/api/users/${userId}`);
      return response.data;
    } catch (error) {
      console.error('Error fetching user:', error);
      return { 
        _id: userId, 
        name: 'Unknown User', 
        image: '/default-avatar.png',
        role: 'user'
      };
    }
  };

  // Load conversations on mount
  useEffect(() => {
    const loadInitialData = async () => {
      setIsLoading(true);
      try {
        // Load conversations
        const convResponse = await axios.get(`/api/conversations?userId=${currentUser._id}`);
        const convos = convResponse.data;
        setConversations(convos);

        // Get unique participants
        const participants = Array.from(new Set(
          convos.flatMap(conv => 
            conv.participants.filter(id => id !== currentUser._id)
          )
        ));

        // Load participant details
        const users = await Promise.all(
          participants.map(id => fetchUserDetails(id))
        );
        setDmList(users);

        // Register socket
        socket.emit('register', currentUser._id);
      } catch (error) {
        console.error('Initial load error:', error);
      } finally {
        setIsLoading(false);
      }
    };

    if (currentUser?._id) {
      loadInitialData();
    }

    return () => {
      socket.off('receiveMessage');
      socket.off('newConversation');
      socket.off('newApplication');
    };
  }, [currentUser]);

  // Socket listeners
  useEffect(() => {
    const handleReceiveMessage = (message) => {
      setMessages(prev => [...prev, message]);
    };

    const handleNewConversation = async (conversation) => {
      const otherParticipantId = conversation.participants.find(
        id => id !== currentUser._id
      );

      if (otherParticipantId && !dmList.some(u => u._id === otherParticipantId)) {
        const user = await fetchUserDetails(otherParticipantId);
        setDmList(prev => [...prev, user]);
      }

      if (!conversations.some(c => c._id === conversation._id)) {
        setConversations(prev => [...prev, conversation]);
      }
    };

    const handleNewApplication = (appData) => {
      setApplications(prev => [...prev, appData]);
      if (currentUser.role === 'client') {
        socket.emit('createConversation', {
          senderId: currentUser._id,
          receiverId: appData.applicantId
        });
      }
    };

    socket.on('receiveMessage', handleReceiveMessage);
    socket.on('newConversation', handleNewConversation);
    socket.on('newApplication', handleNewApplication);

    return () => {
      socket.off('receiveMessage', handleReceiveMessage);
      socket.off('newConversation', handleNewConversation);
      socket.off('newApplication', handleNewApplication);
    };
  }, [currentUser, dmList, conversations]);

  // Load messages when chat is selected
  useEffect(() => {
    const loadMessages = async () => {
      if (!selectedChat) return;

      setIsLoading(true);
      try {
        const response = await axios.get(
          `/api/messages?userId=${currentUser._id}&otherUserId=${selectedChat._id}`
        );
        setMessages(response.data);
      } catch (error) {
        console.error('Error loading messages:', error);
      } finally {
        setIsLoading(false);
      }
    };

    loadMessages();
  }, [selectedChat, currentUser]);

  const handleSend = async () => {
    if (!newMessage.trim() || !selectedChat) return;

    // Declare tempId outside try-catch so it's available in both blocks
    const tempId = Date.now().toString();
    const messageData = {
      sender: currentUser._id,
      receiver: selectedChat._id,
      message: newMessage,
    };

    try {
      // Optimistic update
      setMessages(prev => [...prev, {
        ...messageData,
        _id: tempId,
        timestamp: new Date().toISOString()
      }]);

      // Send to server
      await axios.post('/api/messages', messageData);
      socket.emit('sendMessage', messageData);

      setNewMessage('');
    } catch (error) {
      console.error('Error sending message:', error);
      // Rollback optimistic update
      setMessages(prev => prev.filter(msg => msg._id !== tempId));
    }
  };

  const handleAccept = async () => {
    if (!selectedChat) return;

    try {
      // Update application status
      const response = await axios.put('/api/applications/accept', {
        applicantId: selectedChat._id,
        clientId: currentUser._id
      });

      // Send system message
      const systemMessage = {
        sender: currentUser._id,
        receiver: selectedChat._id,
        message: `${currentUser.name} has accepted your application!`,
        isSystem: true,
        timestamp: new Date().toISOString()
      };

      setMessages(prev => [...prev, systemMessage]);
      socket.emit('sendMessage', systemMessage);

      // Navigate to timeline creation
      navigate('/createTimeline', {
        state: {
          freelancerId: selectedChat._id,
          applicationData: response.data
        }
      });
    } catch (error) {
      console.error('Error accepting application:', error);
      alert('Failed to accept application. Please try again.');
    }
  };

  const renderApplicationMessage = () => {
    if (currentUser.role !== 'client' || !selectedChat) return null;

    const application = applications.find(
      app => app.applicantId === selectedChat._id
    );

    if (!application) return null;

    return (
      <div className="message received application-message">
        <div className="message-content">
          <div className="message-header">
            <span className="sender">{selectedChat.name}</span>
            <span className="timestamp">
              {new Date(application.timestamp).toLocaleString()}
            </span>
          </div>
          <p>
            <strong>Application for Job #{application.jobId}</strong><br />
            <strong>Counter Offer:</strong> ${application.counterOffer}<br />
            <strong>Message:</strong> {application.message}
          </p>
        </div>
      </div>
    );
  };

  return (
    <div className="dm-container">
      {/* Header */}
      <div className="header">
        <img src={currentUser.image || '/default-avatar.png'} alt="Profile" />
        <div className="header-right">
          <span onClick={() => navigate('/home')}>Home</span>
          <span onClick={() => navigate('/profile')}>Profile</span>
          <span onClick={() => navigate('/projects')}>Projects</span>
          <span onClick={() => navigate('/jobs')}>Jobs</span>
        </div>
      </div>

      {/* Main Content */}
      <div className="dm-main">
        {/* Sidebar */}
        <div className="dm-sidebar">
          <h2>Messages</h2>
          {isLoading && !dmList.length ? (
            <div className="loading">Loading conversations...</div>
          ) : (
            dmList.map(user => (
              <div
                key={user._id}
                className={`dm-user ${selectedChat?._id === user._id ? 'active' : ''}`}
                onClick={() => setSelectedChat(user)}
              >
                <img 
                  src={user.image || '/default-avatar.png'} 
                  alt={user.name}
                  className="user-avatar"
                />
                <div className="user-info">
                  <h3>{user.name}</h3>
                  <p>{user.role}</p>
                </div>
              </div>
            ))
          )}
        </div>

        {/* Chat Area */}
        <div className="chat-area">
          {selectedChat ? (
            <>
              <div className="chat-header">
                <div className="chat-user">
                  <img 
                    src={selectedChat.image || '/default-avatar.png'} 
                    alt={selectedChat.name}
                  />
                  <h3>{selectedChat.name}</h3>
                </div>
                {currentUser.role === 'client' && (
                  <button 
                    onClick={handleAccept}
                    className="accept-btn"
                  >
                    Accept Client
                  </button>
                )}
              </div>

              <div className="messages-container">
                {renderApplicationMessage()}
                {messages.map(msg => (
                  <div
                    key={msg._id || msg.timestamp}
                    className={`message ${msg.isSystem ? 'system' : msg.sender === currentUser._id ? 'sent' : 'received'}`}
                  >
                    <div className="message-content">
                      {msg.isSystem ? (
                        <p className="system-message">{msg.message}</p>
                      ) : (
                        <>
                          <div className="message-header">
                            <span className="sender">
                              {msg.sender === currentUser._id ? 'You' : selectedChat.name}
                            </span>
                            <span className="timestamp">
                              {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                            </span>
                          </div>
                          <p>{msg.message}</p>
                        </>
                      )}
                    </div>
                  </div>
                ))}
                <div ref={messagesEndRef} />
              </div>

              <div className="message-input">
                <input
                  type="text"
                  value={newMessage}
                  onChange={(e) => setNewMessage(e.target.value)}
                  placeholder="Type a message..."
                  onKeyPress={(e) => e.key === 'Enter' && handleSend()}
                  disabled={!selectedChat}
                />
                <button 
                  onClick={handleSend}
                  disabled={!newMessage.trim() || !selectedChat}
                >
                  Send
                </button>
              </div>
            </>
          ) : (
            <div className="empty-chat">
              <p>Select a conversation to start chatting</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default DMPage;
